create table if not exists public.federation_remote_interactions (
  id uuid primary key default gen_random_uuid(), local_user_id uuid not null references auth.users(id) on delete cascade,
  object_url text not null, remote_actor_url text, interaction_type text not null check (interaction_type in ('like','repost','reply','quote','bookmark')),
  activity_uri text, target_inbox text, status text not null default 'pending' check (status in ('pending','sent','failed','undone','local_only')),
  payload jsonb not null default '{}'::jsonb, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), expires_at timestamptz
);
create index if not exists idx_fed_remote_interactions_user_object on public.federation_remote_interactions(local_user_id,object_url,interaction_type);
create index if not exists idx_fed_remote_interactions_status on public.federation_remote_interactions(status,updated_at);
create unique index if not exists uq_fed_remote_interaction_active on public.federation_remote_interactions(local_user_id,object_url,interaction_type) where interaction_type in ('like','repost','bookmark') and status <> 'undone';
create table if not exists public.federation_remote_likes (id uuid primary key default gen_random_uuid(), local_user_id uuid not null references auth.users(id) on delete cascade, object_url text not null, remote_actor_url text, activity_uri text, target_inbox text, status text not null default 'pending' check (status in ('pending','sent','failed','undone')), payload jsonb not null default '{}'::jsonb, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), expires_at timestamptz);
create unique index if not exists uq_fed_remote_likes_active on public.federation_remote_likes(local_user_id,object_url) where status <> 'undone';
create table if not exists public.federation_remote_reposts (id uuid primary key default gen_random_uuid(), local_user_id uuid not null references auth.users(id) on delete cascade, object_url text not null, remote_actor_url text, activity_uri text, target_inbox text, status text not null default 'pending' check (status in ('pending','sent','failed','undone')), payload jsonb not null default '{}'::jsonb, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), expires_at timestamptz);
create unique index if not exists uq_fed_remote_reposts_active on public.federation_remote_reposts(local_user_id,object_url) where status <> 'undone';
create table if not exists public.federation_remote_bookmarks (id uuid primary key default gen_random_uuid(), local_user_id uuid not null references auth.users(id) on delete cascade, object_url text not null, remote_actor_url text, status text not null default 'local_only' check (status in ('local_only','removed')), payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), expires_at timestamptz);
create unique index if not exists uq_fed_remote_bookmarks_active on public.federation_remote_bookmarks(local_user_id,object_url) where status = 'local_only';
create table if not exists public.federation_remote_replies (id uuid primary key default gen_random_uuid(), local_user_id uuid not null references auth.users(id) on delete cascade, object_url text not null, remote_actor_url text, activity_uri text not null unique, object_uri text not null unique, target_inbox text, content text not null, status text not null default 'pending' check (status in ('pending','sent','failed','undone')), payload jsonb not null default '{}'::jsonb, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), expires_at timestamptz);
create table if not exists public.federation_remote_quotes (id uuid primary key default gen_random_uuid(), local_user_id uuid not null references auth.users(id) on delete cascade, object_url text not null, remote_actor_url text, activity_uri text not null unique, object_uri text not null unique, target_inbox text, content text not null, status text not null default 'pending' check (status in ('pending','sent','failed','undone')), payload jsonb not null default '{}'::jsonb, error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), expires_at timestamptz);
alter table public.federation_remote_interactions enable row level security; alter table public.federation_remote_likes enable row level security; alter table public.federation_remote_reposts enable row level security; alter table public.federation_remote_bookmarks enable row level security; alter table public.federation_remote_replies enable row level security; alter table public.federation_remote_quotes enable row level security;
drop policy if exists federation_remote_interactions_owner on public.federation_remote_interactions; create policy federation_remote_interactions_owner on public.federation_remote_interactions for all using (local_user_id = auth.uid()) with check (local_user_id = auth.uid());
drop policy if exists federation_remote_likes_owner on public.federation_remote_likes; create policy federation_remote_likes_owner on public.federation_remote_likes for all using (local_user_id = auth.uid()) with check (local_user_id = auth.uid());
drop policy if exists federation_remote_reposts_owner on public.federation_remote_reposts; create policy federation_remote_reposts_owner on public.federation_remote_reposts for all using (local_user_id = auth.uid()) with check (local_user_id = auth.uid());
drop policy if exists federation_remote_bookmarks_owner on public.federation_remote_bookmarks; create policy federation_remote_bookmarks_owner on public.federation_remote_bookmarks for all using (local_user_id = auth.uid()) with check (local_user_id = auth.uid());
drop policy if exists federation_remote_replies_owner on public.federation_remote_replies; create policy federation_remote_replies_owner on public.federation_remote_replies for all using (local_user_id = auth.uid()) with check (local_user_id = auth.uid());
drop policy if exists federation_remote_quotes_owner on public.federation_remote_quotes; create policy federation_remote_quotes_owner on public.federation_remote_quotes for all using (local_user_id = auth.uid()) with check (local_user_id = auth.uid());
create or replace function public.touch_federation_remote_interaction() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
drop trigger if exists trg_touch_federation_remote_interactions on public.federation_remote_interactions; create trigger trg_touch_federation_remote_interactions before update on public.federation_remote_interactions for each row execute function public.touch_federation_remote_interaction(); notify pgrst,'reload schema';
